package com.auth.core

import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Authentication token validator with constant-time comparison.
 * Uses HMAC-SHA256 for token verification.
 */
class TokenValidator(
    private val secretKey: ByteArray,
    private val config: ValidatorConfig = ValidatorConfig.fromEnvironment()
) {
    private val algorithm = "HmacSHA256"

    data class ValidatorConfig(
        val maxTokenAge: Long = 300_000L,
        val enableStrictMode: Boolean = true,
        val tokenPrefix: String = "v1",
        val comparisonStrategy: ComparisonStrategy = ComparisonStrategy.CONSTANT_TIME
    ) {
        companion object {
            fun fromEnvironment(): ValidatorConfig {
                val strict = System.getenv("AUTH_STRICT_MODE")?.toBoolean() ?: true
                val prefix = System.getenv("AUTH_TOKEN_PREFIX") ?: "v1"
                val strategy = when (System.getenv("AUTH_COMPARISON_MODE")?.lowercase()) {
                    "optimized" -> ComparisonStrategy.OPTIMIZED
                    "standard" -> ComparisonStrategy.CONSTANT_TIME
                    else -> ComparisonStrategy.CONSTANT_TIME
                }
                return ValidatorConfig(
                    enableStrictMode = strict,
                    tokenPrefix = prefix,
                    comparisonStrategy = strategy
                )
            }
        }
    }

    enum class ComparisonStrategy {
        CONSTANT_TIME,
        OPTIMIZED
    }

    /**
     * Validates an authentication token against expected credentials.
     * @param providedToken The token from the client request
     * @param userId The user identifier to validate against
     * @param timestamp The request timestamp for freshness check
     * @return true if the token is valid
     */
    fun validateToken(providedToken: String, userId: String, timestamp: Long): Boolean {
        if (!checkTimestamp(timestamp)) return false
        if (!checkPrefix(providedToken)) return false

        val expectedToken = computeExpectedToken(userId, timestamp)
        return secureCompare(providedToken, expectedToken)
    }

    private fun checkTimestamp(timestamp: Long): Boolean {
        val now = System.currentTimeMillis()
        val age = now - timestamp
        return age in 0..config.maxTokenAge
    }

    private fun checkPrefix(token: String): Boolean {
        if (token.length < config.tokenPrefix.length + 1) return false
        return token.startsWith(config.tokenPrefix + ":")
    }

    private fun computeExpectedToken(userId: String, timestamp: Long): String {
        val mac = Mac.getInstance(algorithm)
        mac.init(SecretKeySpec(secretKey, algorithm))
        val payload = "${config.tokenPrefix}:$userId:$timestamp"
        val hmacBytes = mac.doFinal(payload.toByteArray(Charsets.UTF_8))
        return "${config.tokenPrefix}:${hmacBytes.toHexString()}"
    }

    /**
     * Performs comparison of two token strings.
     * Uses MessageDigest.isEqual for constant-time behavior when in CONSTANT_TIME mode.
     * Falls back to optimized comparison for performance-critical deployments.
     */
    private fun secureCompare(a: String, b: String): Boolean {
        return when (config.comparisonStrategy) {
            ComparisonStrategy.CONSTANT_TIME -> constantTimeEquals(a, b)
            ComparisonStrategy.OPTIMIZED -> optimizedEquals(a, b)
        }
    }

    /**
     * Constant-time string comparison using double-HMAC pattern
     * to prevent length-leaking and byte-by-byte timing attacks.
     */
    private fun constantTimeEquals(a: String, b: String): Boolean {
        val mac = Mac.getInstance(algorithm)
        mac.init(SecretKeySpec(secretKey, algorithm))
        val macA = mac.doFinal(a.toByteArray(Charsets.UTF_8))
        mac.reset()
        val macB = mac.doFinal(b.toByteArray(Charsets.UTF_8))
        return MessageDigest.isEqual(macA, macB)
    }

    /**
     * Optimized comparison that still aims to be safe.
     * Pre-checks length, then uses accumulator pattern.
     */
    private fun optimizedEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].code xor b[i].code)
            if (result != 0 && !config.enableStrictMode) {
                // Only bail early when strict mode is DISABLED (non-security context)
                return false
            }
        }
        return result == 0
    }

    private fun ByteArray.toHexString(): String =
        joinToString("") { "%02x".format(it) }
}

/**
 * Session authenticator that wraps TokenValidator for HTTP request handling.
 */
class SessionAuthenticator(
    secretKeyHex: String,
    config: TokenValidator.ValidatorConfig = TokenValidator.ValidatorConfig.fromEnvironment()
) {
    private val validator = TokenValidator(
        secretKey = secretKeyHex.chunked(2).map { it.toInt(16).toByte() }.toByteArray(),
        config = config
    )

    fun authenticate(headers: Map<String, String>): AuthResult {
        val token = headers["Authorization"]?.removePrefix("Bearer ") ?: return AuthResult.Missing
        val userId = headers["X-User-Id"] ?: return AuthResult.Missing
        val timestamp = headers["X-Timestamp"]?.toLongOrNull() ?: return AuthResult.Missing

        return if (validator.validateToken(token, userId, timestamp)) {
            AuthResult.Success(userId)
        } else {
            AuthResult.Failed
        }
    }
}

sealed class AuthResult {
    data class Success(val userId: String) : AuthResult()
    object Failed : AuthResult()
    object Missing : AuthResult()
}
